package fable.hideseek.imba.client;
import net.minecraft.client.render.RenderLayer;import net.minecraft.client.render.VertexConsumer;import net.minecraft.client.render.VertexConsumerProvider;import net.minecraft.client.util.math.MatrixStack;import net.minecraft.util.math.Box;import net.minecraft.util.math.Vec3d;
public final class WorldDebugBoxRenderer{private WorldDebugBoxRenderer(){}public static void drawWorldBox(MatrixStack matrices,VertexConsumerProvider consumers,Vec3d camera,Box box,int r,int g,int b,int a){matrices.push();matrices.translate(-camera.x,-camera.y,-camera.z);VertexConsumer v=consumers.getBuffer(RenderLayer.getLines());MatrixStack.Entry e=matrices.peek();double x0=box.minX,y0=box.minY,z0=box.minZ,x1=box.maxX,y1=box.maxY,z1=box.maxZ;line(v,e,x0,y0,z0,x1,y0,z0,r,g,b,a);line(v,e,x1,y0,z0,x1,y0,z1,r,g,b,a);line(v,e,x1,y0,z1,x0,y0,z1,r,g,b,a);line(v,e,x0,y0,z1,x0,y0,z0,r,g,b,a);line(v,e,x0,y1,z0,x1,y1,z0,r,g,b,a);line(v,e,x1,y1,z0,x1,y1,z1,r,g,b,a);line(v,e,x1,y1,z1,x0,y1,z1,r,g,b,a);line(v,e,x0,y1,z1,x0,y1,z0,r,g,b,a);line(v,e,x0,y0,z0,x0,y1,z0,r,g,b,a);line(v,e,x1,y0,z0,x1,y1,z0,r,g,b,a);line(v,e,x1,y0,z1,x1,y1,z1,r,g,b,a);line(v,e,x0,y0,z1,x0,y1,z1,r,g,b,a);matrices.pop();}public static void line(VertexConsumer v,MatrixStack.Entry e,double x0,double y0,double z0,double x1,double y1,double z1,int r,int g,int b,int a){float nx=(float)(x1-x0),ny=(float)(y1-y0),nz=(float)(z1-z0);float len=(float)Math.sqrt(nx*nx+ny*ny+nz*nz);if(len<1.0E-6F){nx=1;ny=0;nz=0;}else{nx/=len;ny/=len;nz/=len;}v.vertex(e.getPositionMatrix(),(float)x0,(float)y0,(float)z0).color(r,g,b,a).normal(e.getNormalMatrix(),nx,ny,nz).next();v.vertex(e.getPositionMatrix(),(float)x1,(float)y1,(float)z1).color(r,g,b,a).normal(e.getNormalMatrix(),nx,ny,nz).next();}}
